
-- New Letter Templates
ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (1,'Resignation Letter','resignation-letter','A formal letter of resignation from employment with notice period.',50.00,'[{\"name\":\"employee_name\",\"label\":\"Your Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"employee_address\",\"label\":\"Your Address\",\"type\":\"text\",\"required\":true},{\"name\":\"date\",\"label\":\"Date\",\"type\":\"date\",\"required\":true},{\"name\":\"supervisor_title\",\"label\":\"Supervisor Title\",\"type\":\"text\",\"required\":true},{\"name\":\"company_name\",\"label\":\"Company Name\",\"type\":\"text\",\"required\":true},{\"name\":\"position\",\"label\":\"Job Title\",\"type\":\"text\",\"required\":true},{\"name\":\"last_working_day\",\"label\":\"Last Working Day\",\"type\":\"date\",\"required\":true},{\"name\":\"reason\",\"label\":\"Reason\",\"type\":\"textarea\",\"required\":false}]','{\"title\":\"Resignation Letter\",\"sections\":[{\"type\":\"header\",\"content\":\"{{employee_name}}\n{{employee_address}}\nDate: {{date}}\"},{\"type\":\"recipient\",\"content\":\"{{supervisor_title}}\n{{company_name}}\"},{\"type\":\"subject\",\"content\":\"RE: NOTICE OF RESIGNATION FROM POSITION OF {{position}}\"},{\"type\":\"salutation\",\"content\":\"Dear Sir/Madam,\"},{\"type\":\"body\",\"content\":\"Please accept this letter as formal notification of my resignation from {{position}} at {{company_name}}, effective {{last_working_day}}.\n\n{{reason}}\n\nThank you for the opportunity to have worked with {{company_name}}.\"},{\"type\":\"closing\",\"content\":\"Yours sincerely,\n\n\n_____________________\n{{employee_name}}\"}]}',1,6,'Resignation Letter','Generate a Kenyan resignation letter.',NOW(),NOW());

ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (1,'Formal Complaint Letter','complaint-letter','Official complaint to a company, service provider, landlord, or authority.',50.00,'[{\"name\":\"complainant_name\",\"label\":\"Your Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"complainant_contact\",\"label\":\"Your Contact Info\",\"type\":\"text\",\"required\":true},{\"name\":\"date\",\"label\":\"Date\",\"type\":\"date\",\"required\":true},{\"name\":\"recipient_title\",\"label\":\"Recipient / Department\",\"type\":\"text\",\"required\":true},{\"name\":\"organisation\",\"label\":\"Company Name\",\"type\":\"text\",\"required\":true},{\"name\":\"complaint_subject\",\"label\":\"Subject\",\"type\":\"text\",\"required\":true},{\"name\":\"incident_details\",\"label\":\"Incident Details\",\"type\":\"textarea\",\"required\":true},{\"name\":\"demanded_action\",\"label\":\"Action Demanded\",\"type\":\"textarea\",\"required\":true}]','{\"title\":\"Formal Complaint Letter\",\"sections\":[{\"type\":\"header\",\"content\":\"{{complainant_name}}\n{{complainant_contact}}\nDate: {{date}}\"},{\"type\":\"recipient\",\"content\":\"{{recipient_title}}\n{{organisation}}\"},{\"type\":\"subject\",\"content\":\"RE: FORMAL COMPLAINT REGARDING {{complaint_subject}}\"},{\"type\":\"salutation\",\"content\":\"Dear Sir/Madam,\"},{\"type\":\"body\",\"content\":\"I am writing to formally raise a grievance concerning {{complaint_subject}}.\n\n{{incident_details}}\n\nI request that you take the following corrective action without delay:\n\n{{demanded_action}}\"},{\"type\":\"closing\",\"content\":\"Yours faithfully,\n\n\n_____________________\n{{complainant_name}}\"}]}',1,7,'Complaint Letter','Generate formal complaint letter in Kenya.',NOW(),NOW());

ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (1,'Leave Application Letter','leave-application','Request for annual leave, compassionate leave, or sick leave.',50.00,'[{\"name\":\"employee_name\",\"label\":\"Your Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"employee_number\",\"label\":\"Staff ID\",\"type\":\"text\",\"required\":false},{\"name\":\"position\",\"label\":\"Job Title\",\"type\":\"text\",\"required\":true},{\"name\":\"date\",\"label\":\"Date\",\"type\":\"date\",\"required\":true},{\"name\":\"supervisor_name\",\"label\":\"Supervisor Name\",\"type\":\"text\",\"required\":true},{\"name\":\"leave_type\",\"label\":\"Leave Type\",\"type\":\"text\",\"required\":true},{\"name\":\"start_date\",\"label\":\"Start Date\",\"type\":\"date\",\"required\":true},{\"name\":\"end_date\",\"label\":\"End Date\",\"type\":\"date\",\"required\":true},{\"name\":\"handover_person\",\"label\":\"Handover Colleague\",\"type\":\"text\",\"required\":false}]','{\"title\":\"Leave Application Letter\",\"sections\":[{\"type\":\"header\",\"content\":\"{{employee_name}}\nStaff ID: {{employee_number}}\n{{position}}\nDate: {{date}}\"},{\"type\":\"recipient\",\"content\":\"To: {{supervisor_name}}\nHR / Department Head\"},{\"type\":\"subject\",\"content\":\"RE: APPLICATION FOR {{leave_type}} ({{start_date}} TO {{end_date}})\"},{\"type\":\"salutation\",\"content\":\"Dear {{supervisor_name}},\"},{\"type\":\"body\",\"content\":\"I hereby request approval for {{leave_type}} from {{start_date}} to {{end_date}}.\n\nI have briefed {{handover_person}} to oversee my urgent responsibilities.\"},{\"type\":\"closing\",\"content\":\"Yours sincerely,\n\n\n_____________________\n{{employee_name}}\"}]}',1,8,'Leave Application Letter','Generate a leave request letter.',NOW(),NOW());

ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (1,'Formal Demand Letter','demand-letter','Notice demanding immediate payment of debt before legal action.',50.00,'[{\"name\":\"creditor_name\",\"label\":\"Creditor Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"creditor_address\",\"label\":\"Your Address\",\"type\":\"text\",\"required\":true},{\"name\":\"date\",\"label\":\"Date\",\"type\":\"date\",\"required\":true},{\"name\":\"debtor_name\",\"label\":\"Debtor Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"debtor_address\",\"label\":\"Debtor Address\",\"type\":\"text\",\"required\":true},{\"name\":\"amount_owed\",\"label\":\"Amount Owed (KSh)\",\"type\":\"text\",\"required\":true},{\"name\":\"debt_origin\",\"label\":\"Basis of Debt\",\"type\":\"textarea\",\"required\":true},{\"name\":\"deadline_days\",\"label\":\"Notice Period\",\"type\":\"text\",\"required\":true}]','{\"title\":\"Formal Demand Letter\",\"sections\":[{\"type\":\"header\",\"content\":\"FROM:\n{{creditor_name}}\n{{creditor_address}}\nDate: {{date}}\"},{\"type\":\"recipient\",\"content\":\"TO:\n{{debtor_name}}\n{{debtor_address}}\"},{\"type\":\"subject\",\"content\":\"RE: DEMAND FOR PAYMENT OF OUTSTANDING DEBT ({{amount_owed}})\"},{\"type\":\"salutation\",\"content\":\"Dear {{debtor_name}},\"},{\"type\":\"body\",\"content\":\"TAKE NOTICE that you are indebted in the sum of {{amount_owed}} arising from:\n\n{{debt_origin}}\n\nDEMAND IS HEREBY MADE for payment within {{deadline_days}} failing which legal proceedings will commence.\"},{\"type\":\"closing\",\"content\":\"Yours faithfully,\n\n\n_____________________\n{{creditor_name}}\"}]}',1,9,'Formal Demand Letter','Generate legal demand letter in Kenya.',NOW(),NOW());

-- New Affidavit Templates
ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (2,'Affidavit of Lost National ID','affidavit-lost-id','Sworn statement for lost National ID or Passport replacement.',100.00,'[{\"name\":\"deponent_name\",\"label\":\"Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"lost_doc_type\",\"label\":\"Lost Document Type\",\"type\":\"text\",\"required\":true},{\"name\":\"doc_number\",\"label\":\"Document Number\",\"type\":\"text\",\"required\":true},{\"name\":\"date_of_loss\",\"label\":\"Date of Loss\",\"type\":\"text\",\"required\":true},{\"name\":\"place_of_loss\",\"label\":\"Circumstances of Loss\",\"type\":\"textarea\",\"required\":true},{\"name\":\"police_station\",\"label\":\"Police Station\",\"type\":\"text\",\"required\":false}]','{\"title\":\"AFFIDAVIT OF LOST IDENTIFICATION DOCUMENT\",\"sections\":[{\"type\":\"preamble\",\"content\":\"REPUBLIC OF KENYA\nIN THE MATTER OF THE OATHS AND STATUTORY DECLARATIONS ACT (CAP 15)\n\nI, {{deponent_name}}, a resident of Kenya, make oath and state as follows:\"},{\"type\":\"body\",\"content\":\"1. THAT I am the lawful holder of {{lost_doc_type}} No. {{doc_number}}.\n\n2. THAT on or about {{date_of_loss}}, I lost the document around {{place_of_loss}}.\n\n3. THAT the document has not been recovered despite diligent search.\n\n4. THAT this affidavit is sworn to facilitate official replacement.\"},{\"type\":\"jurat\",\"content\":\"SWORN by the said {{deponent_name}}\nBEFORE ME: COMMISSIONER FOR OATHS\nDEPONENT: {{deponent_name}}\"}]}',1,5,'Lost ID Affidavit','Sworn affidavit for lost Kenyan ID.',NOW(),NOW());

ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (2,'Affidavit of Financial Support','affidavit-support','Sworn declaration of financial support for student or dependent.',100.00,'[{\"name\":\"sponsor_name\",\"label\":\"Sponsor Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"sponsor_id\",\"label\":\"Sponsor ID No.\",\"type\":\"text\",\"required\":true},{\"name\":\"sponsor_income\",\"label\":\"Occupation & Income Source\",\"type\":\"text\",\"required\":true},{\"name\":\"beneficiary_name\",\"label\":\"Beneficiary Name\",\"type\":\"text\",\"required\":true},{\"name\":\"relationship\",\"label\":\"Relationship\",\"type\":\"text\",\"required\":true},{\"name\":\"support_purpose\",\"label\":\"Purpose of Support\",\"type\":\"text\",\"required\":true}]','{\"title\":\"AFFIDAVIT OF FINANCIAL SUPPORT\",\"sections\":[{\"type\":\"preamble\",\"content\":\"REPUBLIC OF KENYA\nIN THE MATTER OF THE OATHS AND STATUTORY DECLARATIONS ACT (CAP 15)\n\nI, {{sponsor_name}}, holder of ID No. {{sponsor_id}}, make oath and state as follows:\"},{\"type\":\"body\",\"content\":\"1. THAT I am the {{relationship}} of {{beneficiary_name}}.\n\n2. THAT I am engaged as {{sponsor_income}}.\n\n3. THAT I undertake to unconditionally support {{beneficiary_name}} for {{support_purpose}}.\"},{\"type\":\"jurat\",\"content\":\"SWORN by {{sponsor_name}}\nBEFORE ME: COMMISSIONER FOR OATHS\nDEPONENT: {{sponsor_name}}\"}]}',1,6,'Affidavit of Financial Support','Generate sworn affidavit of support.',NOW(),NOW());

ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (2,'Affidavit of Single Status','affidavit-single-status','Sworn affirmation of bachelorhood / spinsterhood for civil marriage.',100.00,'[{\"name\":\"deponent_name\",\"label\":\"Your Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"id_number\",\"label\":\"National ID No.\",\"type\":\"text\",\"required\":true},{\"name\":\"residence\",\"label\":\"Residence\",\"type\":\"text\",\"required\":true},{\"name\":\"purpose\",\"label\":\"Purpose\",\"type\":\"text\",\"required\":true}]','{\"title\":\"AFFIDAVIT OF SINGLE MARITAL STATUS\",\"sections\":[{\"type\":\"preamble\",\"content\":\"REPUBLIC OF KENYA\nIN THE MATTER OF THE MARRIAGE ACT\n\nI, {{deponent_name}}, ID No. {{id_number}}, resident of {{residence}}, make oath as follows:\"},{\"type\":\"body\",\"content\":\"1. THAT I am an adult of sound mind.\n\n2. THAT I have never contracted any marriage and I am legally single.\n\n3. THAT this affidavit is made for {{purpose}}.\"},{\"type\":\"jurat\",\"content\":\"SWORN by {{deponent_name}}\nBEFORE ME: COMMISSIONER FOR OATHS\nDEPONENT: {{deponent_name}}\"}]}',1,7,'Affidavit of Single Status','Sworn affidavit of single status.',NOW(),NOW());

ame,slug,description,price,schema,definition,is_active,sort_order,meta_title,meta_description,created_at,updated_at) VALUES (2,'Parental Consent for Child Travel','affidavit-child-travel','Sworn parental consent authorizing minor to travel abroad or locally.',100.00,'[{\"name\":\"parent_name\",\"label\":\"Parent Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"parent_id\",\"label\":\"Parent ID No.\",\"type\":\"text\",\"required\":true},{\"name\":\"child_name\",\"label\":\"Child Full Name\",\"type\":\"text\",\"required\":true},{\"name\":\"child_birth_cert\",\"label\":\"Birth Cert No.\",\"type\":\"text\",\"required\":true},{\"name\":\"destination\",\"label\":\"Destination\",\"type\":\"text\",\"required\":true},{\"name\":\"travel_dates\",\"label\":\"Travel Dates\",\"type\":\"text\",\"required\":true},{\"name\":\"accompanying_adult\",\"label\":\"Accompanying Adult\",\"type\":\"text\",\"required\":true}]','{\"title\":\"PARENTAL CONSENT AFFIDAVIT FOR MINOR CHILD TRAVEL\",\"sections\":[{\"type\":\"preamble\",\"content\":\"REPUBLIC OF KENYA\nIN THE MATTER OF THE OATHS AND STATUTORY DECLARATIONS ACT (CAP 15)\n\nI, {{parent_name}}, ID No. {{parent_id}}, make oath and state:\"},{\"type\":\"body\",\"content\":\"1. THAT I am the biological parent of {{child_name}} (Birth Cert: {{child_birth_cert}}).\n\n2. THAT I grant full consent for the minor to travel to {{destination}} between {{travel_dates}} in the care of {{accompanying_adult}}.\"},{\"type\":\"jurat\",\"content\":\"SWORN by {{parent_name}}\nBEFORE ME: COMMISSIONER FOR OATHS\nDEPONENT: {{parent_name}}\"}]}',1,8,'Child Travel Consent Affidavit','Parental consent affidavit for minor travel.',NOW(),NOW());
